styleBlocks.css:
.modal {
  position: relative; cursor: default;
  background: var(--bg-secondary); border-radius: var(--radius);
  border: 1px solid var(--border); width: 90%; max-width: 700px;
  max-height: 85vh; overflow-y: auto; overflow-x: hidden; overscroll-behavior: contain; padding: 32px;
  transform: scale(0.96) translateY(8px); opacity: 0;
  transition: transform 0.25s ease, opacity 0.25s ease;
}

.gb-modal-head .modal-close {
  position: static;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-card);
  color: var(--text-muted);
  font-size: 22px;
  line-height: 1;
  padding: 0;
  flex-shrink: 0;
}

.gb-modal-head .modal-close:hover {
  color: var(--text-primary);
  border-color: var(--accent);
  background: var(--bg-hover);
}

.modal:not(.marker-detail-modal):not(.gb-form-modal):not(.gb-history-modal):not(.settings-modal) > h3:first-of-type,
.modal:not(.marker-detail-modal):not(.gb-form-modal):not(.gb-history-modal):not(.settings-modal) > .modal-header:first-child {
  margin: -32px -32px 20px;
  padding: 22px 56px 18px 26px;
  border-bottom: 1px solid var(--border);
  background: color-mix(in srgb, var(--bg-secondary) 92%, var(--bg-card));
}

.modal:not(.marker-detail-modal):not(.gb-form-modal):not(.gb-history-modal):not(.settings-modal) > h3:first-of-type {
  color: var(--text-primary);
  font-family: var(--font-display);
  font-size: 22px;
  font-weight: 700;
  letter-spacing: 0;
}

.modal:not(.marker-detail-modal):not(.gb-form-modal):not(.gb-history-modal):not(.settings-modal) .modal-actions {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  justify-content: flex-end;
  padding-top: 16px;
  border-top: 1px solid var(--border);
}

.modal-close {
  position: absolute; top: 16px; right: 16px;
  background: none; border: none; color: var(--text-muted);
  font-size: 24px; cursor: pointer; padding: 0 4px;
}

.modal .modal-unit {
  color: var(--text-muted); font-size: 14px; margin-bottom: 8px;
  /* Source-name + delta + trend separated by middle-dots; let them wrap
     gracefully on narrow viewports rather than overflow the modal box. */
  display: flex; flex-wrap: wrap; gap: 4px 6px; align-items: center;
}

.dashboard-sticky-actions .dashboard-action-btn {
  pointer-events: auto;
  background: color-mix(in srgb, var(--bg-secondary) 88%, transparent);
  box-shadow: var(--shadow);
  backdrop-filter: blur(12px);
}

.dashboard-sticky-actions .dashboard-action-btn-primary {
  background: var(--accent);
  border-color: transparent;
  color: var(--on-accent);
}

.dashboard-action-btn {
  padding: 8px 12px; border-radius: var(--radius-sm);
  border: 1px solid var(--border); background: var(--bg-secondary);
  color: var(--text-primary); font: inherit; font-size: 12px; font-weight: 600;
  cursor: pointer; transition: background 0.15s, border-color 0.15s, transform 0.05s;
}

.dashboard-action-btn-primary {
  background: var(--accent); border-color: transparent; color: var(--on-accent);
}

html:not([data-theme]) .dashboard-action-btn-primary {
  /* White hover text fails against the blue accent during background
     interpolation, so this button snaps directly to the dark hover surface. */
  transition: border-color 0.15s, transform 0.05s;
}

html:not([data-theme]) .dashboard-action-btn-primary:hover {
  background: var(--bg-hover);
  border-color: var(--accent);
  color: #fff;
}

.dashboard-widget-tool,
  .lens-widget-dashboard-toggle {
    height: auto;
    min-height: 30px;
    line-height: 1.25;
    white-space: normal;
  }

.db-genome-empty,
.db-correlation-empty {
  width: 100%; min-height: 130px; padding: 18px; border-radius: var(--radius-sm);
  border: 1px dashed var(--border); background: transparent; color: var(--text-primary);
  display: flex; flex-direction: column; align-items: flex-start; justify-content: center;
  gap: 6px; text-align: left; font: inherit;
}

[data-theme="glass"] .dashboard-widget {
  background: color-mix(in srgb, var(--bg-card) 66%, transparent);
  backdrop-filter: blur(24px) saturate(140%);
  -webkit-backdrop-filter: blur(24px) saturate(140%);
}

.dashboard-widgets {
  display: grid; grid-template-columns: repeat(12, minmax(0, 1fr));
  gap: 18px; align-items: start; grid-auto-flow: dense;
}

.dashboard-widgets.is-adaptive > .dashboard-widget {
  grid-column: span var(--widget-columns, 12);
  grid-row: var(--widget-row, auto);
}

.dashboard-widget {
  grid-column: span 12; min-width: 0;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 20px;
  box-shadow: var(--shadow);
  transition: border-color 0.15s, box-shadow 0.15s, transform 0.15s;
}

.dashboard-widget-chrome {
  display: flex; align-items: center; gap: 10px;
  margin-bottom: 14px; min-width: 0;
}

.dashboard-widget-title {
  font-family: var(--font-display); font-size: 14px; font-weight: 700;
  text-transform: uppercase; color: var(--text-primary); letter-spacing: 0;
}

.dashboard-widget-description {
  margin-top: 2px; font-family: var(--font-mono); font-size: 11px; color: var(--text-muted);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}

.dashboard-widget-tool {
  min-width: 30px; height: 30px; padding: 0 9px; border-radius: var(--radius-sm);
  border: 1px solid var(--border); background: var(--bg-secondary);
  color: var(--text-primary); font: inherit; font-size: 12px; cursor: pointer;
}

.dashboard-widget-inline-controls {
  display: flex; align-items: center; gap: 12px; flex-wrap: wrap; margin-bottom: 12px;
}

.dashboard-widget-empty {
  padding: 12px 0; color: var(--text-muted); font-size: 13px; font-style: italic;
}

.dashboard-widgets.is-organizing .dashboard-widget {
  padding: 12px; border: 1px dashed var(--border); border-radius: var(--radius);
  background: color-mix(in srgb, var(--bg-card) 46%, transparent);
}

.dashboard-widgets.is-organizing .dashboard-widget:hover {
  border-color: var(--accent); background: color-mix(in srgb, var(--accent) 5%, var(--bg-card));
}

.marker-detail-modal .modal-close {
  top: 18px;
  right: 20px;
  z-index: 40;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-card);
  color: var(--text-muted);
  font-size: 22px;
  line-height: 1;
  padding: 0;
}

.rec-disclosure-banner {
  background: color-mix(in srgb, var(--accent) 8%, transparent); border: 1px solid color-mix(in srgb, var(--accent) 25%, transparent);
  border-radius: var(--radius); padding: 8px 10px; margin: 12px 0 8px;
  font-size: 12px; line-height: 1.45; color: var(--text-secondary);
}

.rec-disclosure-btn {
  display: inline-block; margin-top: 6px; padding: 2px 10px;
  font-size: 11px; background: transparent; border: 1px solid var(--border);
  border-radius: var(--radius); color: var(--text-muted); cursor: pointer;
}

.rec-drug-warning {
  border-left: 3px solid var(--red); background: rgba(239, 68, 68, 0.06);
  padding: 6px 10px; margin-top: 6px; border-radius: 0 var(--radius) var(--radius) 0;
  font-size: 11px; line-height: 1.4; color: var(--text-secondary);
}
